import{_ as t,o as a,c as i,ae as r}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"Work Packages: Code Review and Governance Process","description":"","frontmatter":{},"headers":[],"relativePath":"specs/022-code-review-and-governance-process/tasks.md","filePath":"specs/022-code-review-and-governance-process/tasks.md"}'),o={name:"specs/022-code-review-and-governance-process/tasks.md"};function n(s,e,d,c,l,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="work-packages-code-review-and-governance-process" tabindex="-1">Work Packages: Code Review and Governance Process <a class="header-anchor" href="#work-packages-code-review-and-governance-process" aria-label="Permalink to &quot;Work Packages: Code Review and Governance Process&quot;">​</a></h1><p><strong>Inputs</strong>: Design documents from <code>/kitty-specs/022-code-review-and-governance-process/</code><strong>Prerequisites</strong>: plan.md (required), spec.md (user stories), spec 021 (CI quality gates)</p><p><strong>Tests</strong>: Include explicit testing work because governance enforcement must be verifiable and complete.</p><p><strong>Organization</strong>: Fine-grained subtasks (<code>Txxx</code>) roll up into work packages (<code>WPxx</code>). Each work package is independently deliverable and testable.</p><p><strong>Prompt Files</strong>: Each work package references a matching prompt file in <code>/kitty-specs/022-code-review-and-governance-process/tasks/</code>.</p><h2 id="subtask-format-txxx-p-description" tabindex="-1">Subtask Format: <code>[Txxx] [P?] Description</code> <a class="header-anchor" href="#subtask-format-txxx-p-description" aria-label="Permalink to &quot;Subtask Format: `[Txxx] [P?] Description`&quot;">​</a></h2><ul><li><strong>[P]</strong> indicates the subtask can proceed in parallel (different files/components).</li><li>Subtasks call out concrete paths in <code>.github/</code>, <code>scripts/</code>, and <code>docs/</code>.</li></ul><hr><h2 id="work-package-wp01-gca-coderabbit-configuration-and-review-requirements-priority-p0" tabindex="-1">Work Package WP01: GCA/CodeRabbit Configuration and Review Requirements (Priority: P0) <a class="header-anchor" href="#work-package-wp01-gca-coderabbit-configuration-and-review-requirements-priority-p0" aria-label="Permalink to &quot;Work Package WP01: GCA/CodeRabbit Configuration and Review Requirements (Priority: P0)&quot;">​</a></h2><p><strong>Phase</strong>: Phase 1 - Review Infrastructure <strong>Goal</strong>: Configure GitHub branch protection, GCA and CodeRabbit as required status checks, agent review requirements, self-merge gating, and the append-only governance log. <strong>Independent Test</strong>: Open a PR, verify merge is blocked until GCA, CodeRabbit, and agent review all pass. Attempt merge without approval and confirm rejection. <strong>Prompt</strong>: <code>/kitty-specs/022-code-review-and-governance-process/tasks/WP01-gca-coderabbit-review-requirements.md</code><strong>Estimated Prompt Size</strong>: ~350 lines</p><h3 id="included-subtasks" tabindex="-1">Included Subtasks <a class="header-anchor" href="#included-subtasks" aria-label="Permalink to &quot;Included Subtasks&quot;">​</a></h3><ul><li>[x] T001 Configure GitHub branch protection rules for <code>main</code>: require status checks (GCA, CodeRabbit, quality-gates), require at least one agent review approval, enforce linear history</li><li>[x] T002 Configure GCA as a GitHub App/integration with required status check, auto-trigger on PR creation and update, and retry logic for rate-limiting</li><li>[x] T003 Configure CodeRabbit as a required status check with auto-trigger and rate-limit retry</li><li>[x] T004 Implement self-merge gating logic: verify all CI gates pass AND all required reviews approved before allowing merge</li><li>[x] T005 Create append-only governance log (<code>governance-log.jsonl</code>) with schema: PR number, author, reviewers, gate results, compliance attestation, exception ADRs, timestamp</li><li>[x] T006 [P] Implement <code>scripts/governance-log.ts</code> utility for appending entries and querying the log (e.g., self-merges in last 30 days, exception ADRs)</li></ul><h3 id="implementation-notes" tabindex="-1">Implementation Notes <a class="header-anchor" href="#implementation-notes" aria-label="Permalink to &quot;Implementation Notes&quot;">​</a></h3><ul><li>Branch protection must be documented in <code>.github/branch-protection.md</code> for reproducibility.</li><li>Rate-limited review tools block merge; no fallback-to-skip.</li><li>Governance log must be append-only and version-controlled.</li></ul><h3 id="parallel-opportunities" tabindex="-1">Parallel Opportunities <a class="header-anchor" href="#parallel-opportunities" aria-label="Permalink to &quot;Parallel Opportunities&quot;">​</a></h3><ul><li>T006 can proceed after T005 schema is defined.</li></ul><h3 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h3><ul><li>Depends on spec 021 (CI quality gates as required status checks).</li></ul><h3 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h3><ul><li>Risk: GCA or CodeRabbit rate limits cause persistent merge blocks.</li><li>Mitigation: Implement exponential backoff retry with notification to author.</li></ul><hr><h2 id="work-package-wp02-constitution-compliance-checker-adr-exception-workflow-and-tests-priority-p1" tabindex="-1">Work Package WP02: Constitution Compliance Checker, ADR Exception Workflow, and Tests (Priority: P1) <a class="header-anchor" href="#work-package-wp02-constitution-compliance-checker-adr-exception-workflow-and-tests-priority-p1" aria-label="Permalink to &quot;Work Package WP02: Constitution Compliance Checker, ADR Exception Workflow, and Tests (Priority: P1)&quot;">​</a></h2><p><strong>Goal</strong>: Deliver a constitution compliance checker that validates every PR against the full review checklist, an ADR exception workflow requiring 3 approvals and sunset dates, and comprehensive tests. <strong>Independent Test</strong>: Open a PR that violates a constitution requirement, verify the compliance checker flags it with the specific constitution section reference. <strong>Prompt</strong>: <code>/kitty-specs/022-code-review-and-governance-process/tasks/WP02-compliance-checker-and-adr-workflow.md</code><strong>Estimated Prompt Size</strong>: ~380 lines</p><h3 id="included-subtasks-1" tabindex="-1">Included Subtasks <a class="header-anchor" href="#included-subtasks-1" aria-label="Permalink to &quot;Included Subtasks&quot;">​</a></h3><ul><li>[x] T007 Implement <code>scripts/compliance-checker.ts</code> that validates PR changesets against the constitution review checklist: correctness, tests, docs, types, error handling, performance, security, anti-patterns, library preference, backward-compat avoidance, regression risk</li><li>[x] T008 Implement constitution section referencing: each finding links to the specific section in <code>docs/reference/constitution.md</code></li><li>[x] T009 Create <code>.github/workflows/compliance-check.yml</code> GitHub Action that runs the compliance checker on every PR and reports results as a required status check</li><li>[x] T010 Implement ADR exception workflow: validate linked ADRs have sunset dates (or permanence justification), require 3 approvals, store ADRs in <code>docs/adrs/</code></li><li>[x] T011 [P] Add compliance checker unit tests: deliberate violations (missing tests, file &gt; 500 lines, missing types) are caught with correct constitution references</li><li>[x] T012 [P] Add ADR workflow tests: ADR without sunset date rejected, ADR with sunset date and 3 approvals accepted, governance log entry created on merge</li></ul><h3 id="implementation-notes-1" tabindex="-1">Implementation Notes <a class="header-anchor" href="#implementation-notes-1" aria-label="Permalink to &quot;Implementation Notes&quot;">​</a></h3><ul><li>Compliance checker must read the constitution dynamically so amendments are automatically reflected.</li><li>Each finding must include a remediation hint, not just the violation.</li><li>ADR exception workflow integrates with the governance log.</li></ul><h3 id="parallel-opportunities-1" tabindex="-1">Parallel Opportunities <a class="header-anchor" href="#parallel-opportunities-1" aria-label="Permalink to &quot;Parallel Opportunities&quot;">​</a></h3><ul><li>T011 and T012 can proceed after T007 and T010 interfaces are stable.</li></ul><h3 id="dependencies-1" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies-1" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h3><ul><li>Depends on WP01.</li></ul><h3 id="risks-mitigations-1" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations-1" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h3><ul><li>Risk: Constitution amendments change review requirements during open PRs.</li><li>Mitigation: Compliance checker reads constitution at check time; re-evaluation documented as slice-2.</li></ul><hr><h2 id="dependency-execution-summary" tabindex="-1">Dependency &amp; Execution Summary <a class="header-anchor" href="#dependency-execution-summary" aria-label="Permalink to &quot;Dependency &amp; Execution Summary&quot;">​</a></h2><ul><li><strong>Sequence</strong>: WP01 → WP02.</li><li><strong>Parallelization</strong>: Within WP01, T006 after T005; within WP02, T011/T012 after T007/T010.</li><li><strong>MVP Scope</strong>: Both WPs required for constitution-compliant governance.</li></ul><hr><h2 id="subtask-index-reference" tabindex="-1">Subtask Index (Reference) <a class="header-anchor" href="#subtask-index-reference" aria-label="Permalink to &quot;Subtask Index (Reference)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Subtask ID</th><th>Summary</th><th>Work Package</th><th>Priority</th><th>Parallel?</th></tr></thead><tbody><tr><td>T001</td><td>Branch protection rules</td><td>WP01</td><td>P0</td><td>No</td></tr><tr><td>T002</td><td>GCA integration + retry</td><td>WP01</td><td>P0</td><td>No</td></tr><tr><td>T003</td><td>CodeRabbit integration + retry</td><td>WP01</td><td>P0</td><td>No</td></tr><tr><td>T004</td><td>Self-merge gating logic</td><td>WP01</td><td>P0</td><td>No</td></tr><tr><td>T005</td><td>Governance log schema + file</td><td>WP01</td><td>P0</td><td>No</td></tr><tr><td>T006</td><td>Governance log utility</td><td>WP01</td><td>P0</td><td>Yes</td></tr><tr><td>T007</td><td>Compliance checker implementation</td><td>WP02</td><td>P1</td><td>No</td></tr><tr><td>T008</td><td>Constitution section referencing</td><td>WP02</td><td>P1</td><td>No</td></tr><tr><td>T009</td><td>Compliance check GitHub Action</td><td>WP02</td><td>P1</td><td>No</td></tr><tr><td>T010</td><td>ADR exception workflow</td><td>WP02</td><td>P1</td><td>No</td></tr><tr><td>T011</td><td>Compliance checker tests</td><td>WP02</td><td>P1</td><td>Yes</td></tr><tr><td>T012</td><td>ADR workflow tests</td><td>WP02</td><td>P1</td><td>Yes</td></tr></tbody></table>',39)])])}const m=t(o,[["render",n]]);export{h as __pageData,m as default};
